// Favicon assets for the dashboard, generated from the HercuIT Burnrate brand kit.
// Base64-encoded so they can be served directly from the Worker with no static-asset binding.

export interface StaticAsset {
    contentType: string;
    base64: string;
}

export const faviconAssets: Record<string, StaticAsset> = {
    '/favicon.ico': { contentType: 'image/x-icon', base64: '' },
    '/favicon.svg': { contentType: 'image/svg+xml', base64: '' },
    '/favicon-16.png': { contentType: 'image/png', base64: '' },
    '/favicon-32.png': { contentType: 'image/png', base64: '' },
    '/favicon-192.png': { contentType: 'image/png', base64: '' },
    '/favicon-512.png': { contentType: 'image/png', base64: '' },
    '/apple-touch-icon.png': { contentType: 'image/png', base64: '' },
};
